<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue'
import{ElMessage,ElMessageBox}from'element-plus'
import{useAuthStore}from'../../stores/auth'
import{cancelBill,createBill,getBills,getPatients,payBill}from'../../services/operations'
import type{BillingRecord,PatientSummary}from'../../types/medical'
const auth=useAuthStore(),isAdmin=computed(()=>auth.user?.role==='admin'),isPatient=computed(()=>auth.user?.role==='patient'),rows=ref<BillingRecord[]>([]),patients=ref<PatientSummary[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false),status=ref('')
const form=reactive({patient_id:undefined as number|undefined,category:'other',description:'',amount:0})
const categories=[['registration','挂号费'],['examination','检查费'],['medicine','药品费'],['inpatient','住院费'],['other','其他']]
function errorText(e:any,fallback:string){const errors=e.response?.data?.errors;if(errors){const first=Object.values(errors)[0] as string|string[]|undefined;if(first)return Array.isArray(first)?first.join('；'):String(first)}return e.response?.data?.detail||fallback}
async function load(){loading.value=true;try{rows.value=(await getBills({status:status.value||undefined})).results}finally{loading.value=false}}
async function open(){Object.assign(form,{patient_id:undefined,category:'other',description:'',amount:0});dialog.value=true;if(!patients.value.length)patients.value=await getPatients()}
async function submit(){if(!form.patient_id||!form.description.trim()||form.amount<=0){ElMessage.warning('请完整填写账单信息');return}saving.value=true;try{await createBill(form);ElMessage.success('账单已创建');dialog.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'创建失败')}finally{saving.value=false}}
async function pay(row:BillingRecord){try{await ElMessageBox.confirm(row.prescription_no?`确认支付 ¥${row.amount}？支付后将自动发放处方药品并扣减库存。`:`确认结算 ¥${row.amount}？`,'费用结算',{type:'info'});await payBill(row.id);ElMessage.success(row.prescription_no?'支付成功，药品已发放':'结算成功');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e,'结算失败'))}}
async function cancel(row:BillingRecord){try{await ElMessageBox.confirm('确认取消该账单？','取消账单',{type:'warning'});await cancelBill(row.id);await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'取消失败')}}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">BILLING & SETTLEMENT</p><h1>{{isPatient?'我的费用':'费用结算'}}</h1><p>药品账单支付成功后将自动发药、扣减库存并计入医院收入</p></div><el-button v-if="isAdmin" type="primary" @click="open">＋ 创建账单</el-button></div><el-card class="table-card"><div class="table-tools"><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option label="待缴费" value="unpaid"/><el-option label="已缴费" value="paid"/><el-option label="已取消" value="cancelled"/></el-select></div><el-table v-loading="loading" :data="rows"><el-table-column prop="bill_no" label="账单号" min-width="150"/><el-table-column v-if="!isPatient" prop="patient_name" label="患者"/><el-table-column prop="prescription_no" label="关联处方" min-width="145"><template #default="{row}">{{row.prescription_no||'—'}}</template></el-table-column><el-table-column prop="category_display" label="费用类别"/><el-table-column prop="description" label="费用说明" min-width="220"/><el-table-column label="金额" width="120"><template #default="{row}"><b>¥{{row.amount}}</b></template></el-table-column><el-table-column prop="status_display" label="状态"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button v-if="row.status==='unpaid'&&(isPatient||isAdmin)" link type="success" @click="pay(row)">{{row.prescription_no?'支付并取药':'结算'}}</el-button><el-button v-if="row.status==='unpaid'&&isAdmin" link type="danger" @click="cancel(row)">取消</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="创建费用账单" width="min(560px,94vw)"><el-form label-position="top"><el-form-item label="患者" required><el-select v-model="form.patient_id" filterable style="width:100%"><el-option v-for="item in patients" :key="item.id" :label="`${item.full_name} · ${item.patient_no}`" :value="item.id"/></el-select></el-form-item><el-row :gutter="14"><el-col :span="12"><el-form-item label="类别"><el-select v-model="form.category" style="width:100%"><el-option v-for="item in categories" :key="item[0]" :label="item[1]" :value="item[0]"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="金额" required><el-input-number v-model="form.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="费用说明" required><el-input v-model="form.description"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">创建账单</el-button></template></el-dialog></section></template>
